"""
Test edge cases for annotated types serialization strategy.
"""

from dataclasses import dataclass
from typing import Annotated, List, Dict
from typing_extensions import TypeAlias
from mashumaro import DataClassDictMixin


# More complex annotated types
PositiveInt: TypeAlias = Annotated[int, "PositiveInt"]
EmailStr: TypeAlias = Annotated[str, "EmailStr"] 
ComplexList: TypeAlias = Annotated[List[int], "ComplexList"]


def deserialize_positive_int(value):
    print(f"[POSITIVE_INT] deserialize_positive_int called with {value}")
    if value < 0:
        raise ValueError("value < 0")
    return value


def deserialize_email_str(value):
    print(f"[EMAIL_STR] deserialize_email_str called with {value}")
    if "@" not in value:
        raise ValueError("Invalid email")
    return value.lower()


def deserialize_complex_list(value):
    print(f"[COMPLEX_LIST] deserialize_complex_list called with {value}")
    # Custom logic: only allow lists with even number of elements
    if len(value) % 2 != 0:
        raise ValueError("List must have even number of elements")
    return [x * 2 for x in value]  # Double each element


@dataclass
class ComplexTestClass(DataClassDictMixin):
    pos_int: PositiveInt
    email: EmailStr
    complex_list: ComplexList

    class Config:
        serialization_strategy = {
            PositiveInt: {"deserialize": deserialize_positive_int},
            EmailStr: {"deserialize": deserialize_email_str},
            ComplexList: {"deserialize": deserialize_complex_list},
        }


def test_complex_annotated_types():
    print("=== Testing Complex Annotated Types ===")

    try:
        # Valid case
        obj = ComplexTestClass.from_dict({
            "pos_int": 5,
            "email": "TEST@EXAMPLE.COM",
            "complex_list": [1, 2, 3, 4]
        })
        print(f"Success: {obj}")
        # Expected: pos_int=5, email="test@example.com", complex_list=[2, 4, 6, 8]

        # Test validations
        print("\n--- Testing validation errors ---")

        # Negative positive int
        try:
            ComplexTestClass.from_dict({
                "pos_int": -5,
                "email": "test@example.com", 
                "complex_list": [1, 2]
            })
        except Exception as e:
            print(f"Caught negative int error: {e}")

        # Invalid email
        try:
            ComplexTestClass.from_dict({
                "pos_int": 5,
                "email": "invalid-email",
                "complex_list": [1, 2]
            })
        except Exception as e:
            print(f"Caught invalid email error: {e}")

        # Odd length list
        try:
            ComplexTestClass.from_dict({
                "pos_int": 5,
                "email": "test@example.com",
                "complex_list": [1, 2, 3]
            })
        except Exception as e:
            print(f"Caught odd list error: {e}")

    except Exception as e:
        print(f"Unexpected error: {e}")


# Test nested annotated types
NestedAnnotated: TypeAlias = Annotated[PositiveInt, "Nested"]  # Annotated[Annotated[int, ...], ...]


def deserialize_nested(value):
    print(f"[NESTED] deserialize_nested called with {value}")
    if value <= 10:
        raise ValueError("Must be greater than 10")
    return value


@dataclass
class NestedTestClass(DataClassDictMixin):
    nested_val: NestedAnnotated

    class Config:
        serialization_strategy = {
            NestedAnnotated: {"deserialize": deserialize_nested},
            PositiveInt: {"deserialize": deserialize_positive_int},
        }


def test_nested_annotated():
    print("\n=== Testing Nested Annotated Types ===")

    try:
        # This should use the nested strategy
        obj = NestedTestClass.from_dict({"nested_val": 15})
        print(f"Success: {obj}")

        # Test validation
        try:
            NestedTestClass.from_dict({"nested_val": 5})  # Should fail nested validation (>10)
        except Exception as e:
            print(f"Caught nested validation error: {e}")

    except Exception as e:
        print(f"Unexpected error: {e}")


if __name__ == "__main__":
    test_complex_annotated_types()
    test_nested_annotated()

