        raise ValueError("value >= 0")
    return value


# Test 1: What happens if we have field-level serialization strategy?
@dataclass
class FieldLevelStrategy(DataClassDictMixin):
    positive_int: PositiveInt = field(metadata={
        "deserialize": lambda x: print(f"FIELD STRATEGY: {x}") or x + 999
    })
    negative_int: NegativeInt

    class Config:
        serialization_strategy = {
            NegativeInt: {"deserialize": deserialize_negative_int},
        }


# Test 2: What if we mix field and class strategies for the same annotated type?
