class MixedStrategies(DataClassDictMixin):
    positive_int: PositiveInt = field(metadata={
        "deserialize": lambda x: print(f"FIELD STRATEGY: {x}") or x + 999
    })

    class Config:
        serialization_strategy = {
            PositiveInt: {"deserialize": deserialize_positive_int},
        }


# Test 3: What about generic annotated types?
