AnnotatedListOfInt: TypeAlias = Annotated[List[int], "AnnotatedListOfInt"]


def deserialize_annotated_list(value):
    print(f"[ANNOTATED_LIST] deserialize_annotated_list called with {value}")
    return [x + 1000 for x in value]


