    my_list: AnnotatedListOfInt

    class Config:
        serialization_strategy = {
            AnnotatedListOfInt: {"deserialize": deserialize_annotated_list},
        }


def test_field_level_strategy():
    print("=== Test 1: Field Level Strategy ===")
    try:
        obj = FieldLevelStrategy.from_dict({
            "positive_int": 5,
            "negative_int": -3
        })
        print(f"Success: {obj}")
        # Field strategy should override class strategy for positive_int
    except Exception as e:
        print(f"Error: {e}")


