def test_generic_annotated():
    print("\n=== Test 3: Generic Annotated Types ===")
    try:
        obj = GenericAnnotatedTest.from_dict({"my_list": [1, 2, 3]})
        print(f"Success: {obj}")
        # Should be [1001, 1002, 1003]
    except Exception as e:
        print(f"Error: {e}")


if __name__ == "__main__":
    test_field_level_strategy()
    test_mixed_strategies()
